const SCOPE='openid email profile https://www.googleapis.com/auth/drive',FOLDER='application/vnd.google-apps.folder';
const state={accounts:[],selected:'all',folders:{},history:{},files:[],selectedFiles:new Set(),sort:'name',query:'',clipboard:null,undo:[]};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>{if(n==null)return'—';n=Number(n);let i=0,u=['B','KB','MB','GB','TB'];while(n>=1024&&i<4){n/=1024;i++}return n.toFixed(i?1:0)+' '+u[i]};
function toast(t){let e=$('#toast');e.textContent=t;e.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>e.hidden=true,4500)}
function clientId(){return localStorage.getItem('fd.webClientId')||''}
async function api(a,path,o={}){let r=await fetch('https://www.googleapis.com'+path,{...o,headers:{Authorization:'Bearer '+a.token,...(o.headers||{})}});if(!r.ok){let x=await r.json().catch(()=>({}));throw Error(x.error?.message||`Google request failed (${r.status})`)}return r.status===204?null:r.json()}
function account(id=state.selected){return state.accounts.find(a=>a.id===id)}
function initNav(a){if(!state.folders[a.id])state.folders[a.id]=[{id:'root',name:'My Drive'}];if(!state.history[a.id])state.history[a.id]={items:[clone(state.folders[a.id])],index:0}}
function clone(p){return p.map(x=>({...x}))}function currentFolder(a){initNav(a);return state.folders[a.id].at(-1)}
function setPath(a,path,record=true){initNav(a);state.folders[a.id]=clone(path);if(record){let h=state.history[a.id];h.items=h.items.slice(0,h.index+1);h.items.push(clone(path));h.index=h.items.length-1}}
function authorize(){if(!clientId()){openSettings();return toast('Add your Google Web Client ID first.')}if(!window.google?.accounts?.oauth2)return toast('Google sign-in is still loading.');google.accounts.oauth2.initTokenClient({client_id:clientId(),scope:SCOPE,prompt:'select_account consent',callback:async r=>{if(r.error)return toast(r.error_description||r.error);try{let p=await fetch('https://www.googleapis.com/oauth2/v3/userinfo',{headers:{Authorization:'Bearer '+r.access_token}}).then(x=>x.json()),about=await api({token:r.access_token},'/drive/v3/about?fields=storageQuota,user'),old=state.accounts.find(a=>a.email===p.email),a={id:p.sub,email:p.email,name:p.name||p.email,token:r.access_token,quota:about.storageQuota||{}};old?Object.assign(old,a):state.accounts.push(a);state.selected=a.id;initNav(a);await load();toast('Google account connected.')}catch(e){toast(e.message)}}}).requestAccessToken()}
async function listFor(a){let q=encodeURIComponent(`'${currentFolder(a).id}' in parents and trashed=false`),d=await api(a,`/drive/v3/files?q=${q}&pageSize=1000&orderBy=folder,name&fields=files(id,name,mimeType,size,modifiedTime,webViewLink,parents,capabilities(canDownload))`);return d.files.map(f=>({...f,accountId:a.id,accountEmail:a.email}))}
async function load(){try{$('#files').innerHTML='<tr><td colspan="6">Loading…</td></tr>';let targets=state.selected==='all'?state.accounts:[account()],groups=await Promise.all(targets.filter(Boolean).map(listFor));state.files=groups.flat();state.selectedFiles.clear();render()}catch(e){state.files=[];render();toast(e.message)}}
function renderAccounts(){$('#accounts').innerHTML=state.accounts.map(a=>`<button class="drive-item ${state.selected===a.id?'active':''}" data-account="${esc(a.id)}"><span class="account-dot">${esc(a.name[0])}</span><span><b>${esc(a.name)}</b><small>${esc(a.email)}</small></span></button>`).join('');$$('[data-account]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.account;initNav(account());load()})}
function totals(){let limit=0,used=0,known=true;state.accounts.forEach(a=>{used+=Number(a.quota.usage||0);if(a.quota.limit==null)known=false;else limit+=Number(a.quota.limit)});let pct=limit?Math.min(100,used/limit*100):0,free=known?Math.max(0,limit-used):null;$('#storage').innerHTML=[['TOTAL STORAGE',known?fmt(limit):'Mixed / unknown',pct],['USED',fmt(used),pct],['FREE',fmt(free),100-pct]].map(x=>`<div class="stat"><span>${x[0]}</span><b>${x[1]}</b><div class="meter"><i style="width:${x[2]}%"></i></div></div>`).join('')}
function icon(f){return f.mimeType===FOLDER?'📁':f.mimeType?.includes('image')?'▧':f.mimeType?.includes('audio')?'♫':f.mimeType?.includes('video')?'▶':'▤'}
function visibleFiles(){let rows=state.files.filter(f=>!state.query||f.name.toLowerCase().includes(state.query)),k=state.sort;return rows.sort((a,b)=>k==='size'?Number(a.size||0)-Number(b.size||0):k==='modifiedTime'?String(b[k]).localeCompare(String(a[k])):String(a[k]||'').localeCompare(String(b[k]||''),undefined,{numeric:true,sensitivity:'base'}))}
function render(){renderAccounts();totals();let a=account(),all=state.selected==='all';$('#viewTitle').textContent=all?'All Drives':a.name;$('#breadcrumb').innerHTML=all?'All connected accounts':state.folders[a.id].map((f,i)=>`<button data-crumb="${i}">${esc(f.name)}</button>${i<state.folders[a.id].length-1?' / ':''}`).join('');$$('[data-crumb]').forEach(b=>b.onclick=()=>{setPath(a,state.folders[a.id].slice(0,+b.dataset.crumb+1));load()});let rows=visibleFiles();$('#files').innerHTML=rows.map(f=>{let k=f.accountId+':'+f.id;return `<tr><td><input type="checkbox" data-select="${k}" ${state.selectedFiles.has(k)?'checked':''}></td><td><div class="file-name" data-open="${k}" title="Double-click to open"><span class="file-icon">${icon(f)}</span><span>${esc(f.name)}</span></div></td><td>${esc(f.accountEmail)}</td><td>${f.mimeType===FOLDER?'—':fmt(f.size)}</td><td>${f.modifiedTime?new Date(f.modifiedTime).toLocaleString():'—'}</td><td class="row-actions"><button data-row-open="${k}">Open</button>${f.mimeType!==FOLDER?`<button data-row-download="${k}" title="Download">⇩</button>`:''}</td></tr>`}).join('');$('#empty').style.display=rows.length?'none':'flex';$$('[data-select]').forEach(x=>x.onchange=()=>{x.checked?state.selectedFiles.add(x.dataset.select):state.selectedFiles.delete(x.dataset.select);buttons()});$$('[data-open]').forEach(x=>x.ondblclick=()=>openItem(x.dataset.open));$$('[data-row-open]').forEach(x=>x.onclick=()=>openItem(x.dataset.rowOpen));$$('[data-row-download]').forEach(x=>x.onclick=()=>downloadItem(x.dataset.rowDownload));$('#selectAll').checked=rows.length>0&&rows.every(f=>state.selectedFiles.has(f.accountId+':'+f.id));buttons()}
function getItem(k){let p=k.lastIndexOf(':');return state.files.find(f=>f.accountId===k.slice(0,p)&&f.id===k.slice(p+1))}function chosen(){return [...state.selectedFiles].map(getItem).filter(Boolean)}
async function openItem(k){let f=getItem(k);if(!f)return;let a=account(f.accountId);if(f.mimeType===FOLDER){state.selected=a.id;setPath(a,[...state.folders[a.id],{id:f.id,name:f.name}]);await load()}else if(f.webViewLink)window.open(f.webViewLink,'_blank','noopener')}
async function openChosen(){for(let f of chosen())await openItem(f.accountId+':'+f.id)}
async function downloadItem(k){let f=getItem(k);if(!f||f.mimeType===FOLDER)return;let a=account(f.accountId);if(f.mimeType.startsWith('application/vnd.google-apps.')){if(f.webViewLink)window.open(f.webViewLink,'_blank','noopener');return toast('Google document opened; use its Download command to select an export format.')}try{toast('Preparing '+f.name+'…');let r=await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(f.id)}?alt=media`,{headers:{Authorization:'Bearer '+a.token}});if(!r.ok)throw Error(`Download failed (${r.status})`);let u=URL.createObjectURL(await r.blob()),l=document.createElement('a');l.href=u;l.download=f.name;l.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}catch(e){toast(e.message)}}
async function downloadChosen(){for(let f of chosen())await downloadItem(f.accountId+':'+f.id)}
function buttons(){let n=state.selectedFiles.size,items=chosen(),a=account(),h=a&&state.history[a.id],all=state.selected==='all';$('#openBtn').disabled=!n;$('#downloadBtn').disabled=!n||items.some(f=>f.mimeType===FOLDER);$('#copyBtn').disabled=!n;$('#cutBtn').disabled=!n;$('#renameBtn').disabled=n!==1;$('#deleteBtn').disabled=!n;$('#pasteBtn').disabled=!state.clipboard;$('#undoBtn').disabled=!state.undo.length;$('#selectionInfo').textContent=n?`${n} selected`:'';$('#backBtn').disabled=all||!h||h.index<=0;$('#forwardBtn').disabled=all||!h||h.index>=h.items.length-1;$('#upBtn').disabled=all||!a||state.folders[a.id].length<=1;$('#homeBtn').disabled=!state.accounts.length}
function pushUndo(x,label){state.undo.push(x);if(state.undo.length>20)state.undo.shift();buttons();toast(label+' — Undo is available.')}
async function createFolder(){let a=account();if(!a)return toast('Open one Google account first.');let name=prompt('Folder name')?.trim();if(!name)return;let f=await api(a,'/drive/v3/files?fields=id',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,mimeType:FOLDER,parents:[currentFolder(a).id]})});pushUndo({type:'created',items:[{accountId:a.id,id:f.id}]},'Folder created');await load()}
async function rename(){let f=chosen()[0],a=account(f.accountId),name=prompt('New name',f.name)?.trim();if(!name||name===f.name)return;await api(a,`/drive/v3/files/${encodeURIComponent(f.id)}?fields=id`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});pushUndo({type:'rename',accountId:a.id,id:f.id,name:f.name},'Renamed');await load()}
async function trash(){let items=chosen();if(!items.length||!confirm('Move selected item(s) to Google Drive Trash? You can immediately use Undo.'))return;for(let f of items)await api(account(f.accountId),`/drive/v3/files/${encodeURIComponent(f.id)}?fields=id`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:'{"trashed":true}'});pushUndo({type:'trash',items:items.map(f=>({accountId:f.accountId,id:f.id}))},'Moved to Trash');await load()}
async function paste(){let dst=account();if(!dst)return toast('Open one destination account first.');let parent=currentFolder(dst).id,clip=state.clipboard,u=[];try{for(let f of clip.items){let src=account(f.accountId);if(src.id!==dst.id)throw Error('For cross-account browser transfer, download then upload the file.');if(clip.mode==='copy'){let made=await api(src,`/drive/v3/files/${encodeURIComponent(f.id)}/copy?fields=id`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({parents:[parent],name:f.name})});u.push({accountId:src.id,id:made.id})}else{let old=f.parents||[];await api(src,`/drive/v3/files/${encodeURIComponent(f.id)}?addParents=${encodeURIComponent(parent)}&removeParents=${encodeURIComponent(old.join(','))}&fields=id`,{method:'PATCH'});u.push({accountId:src.id,id:f.id,oldParents:old,newParent:parent})}}pushUndo({type:clip.mode==='copy'?'created':'move',items:u},clip.mode==='copy'?'Pasted copies':'Moved');if(clip.mode==='cut')state.clipboard=null;await load()}catch(e){toast(e.message)}}
async function undo(){let x=state.undo.pop();if(!x)return;try{if(x.type==='rename')await api(account(x.accountId),`/drive/v3/files/${encodeURIComponent(x.id)}?fields=id`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:x.name})});else if(x.type==='trash')for(let i of x.items)await api(account(i.accountId),`/drive/v3/files/${encodeURIComponent(i.id)}?fields=id`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:'{"trashed":false}'});else if(x.type==='created')for(let i of x.items)await api(account(i.accountId),`/drive/v3/files/${encodeURIComponent(i.id)}?fields=id`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:'{"trashed":true}'});else for(let i of x.items)await api(account(i.accountId),`/drive/v3/files/${encodeURIComponent(i.id)}?addParents=${encodeURIComponent(i.oldParents.join(','))}&removeParents=${encodeURIComponent(i.newParent)}&fields=id`,{method:'PATCH'});await load();toast('Last action undone.')}catch(e){state.undo.push(x);buttons();toast('Undo failed: '+e.message)}}
async function upload(files){let a=account()||[...state.accounts].sort((x,y)=>(+y.quota.limit-+y.quota.usage)-(+x.quota.limit-+x.quota.usage))[0];if(!a)return toast('Connect a Google account first.');let parent=currentFolder(a).id;for(let i=0;i<files.length;i++){let f=files[i],q=$('#queue'),b='fd'+Date.now();q.hidden=false;q.innerHTML=`Uploading ${esc(f.name)} (${i+1}/${files.length})<div class="progress"><i style="width:${i/files.length*100}%"></i></div>`;let body=new Blob([`--${b}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n`,JSON.stringify({name:f.name,parents:[parent]}),`\r\n--${b}\r\nContent-Type: ${f.type||'application/octet-stream'}\r\n\r\n`,f,`\r\n--${b}--`]);await api(a,'/upload/drive/v3/files?uploadType=multipart&fields=id',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+b},body})}$('#queue').hidden=true;await load();toast(files.length+' file(s) uploaded.')}
function navigate(mode){let a=account();if(!a)return;if(mode==='home')setPath(a,[state.folders[a.id][0]]);else if(mode==='up'){if(state.folders[a.id].length<=1)return;setPath(a,state.folders[a.id].slice(0,-1))}else{let h=state.history[a.id],i=h.index+(mode==='back'?-1:1);if(i<0||i>=h.items.length)return;h.index=i;state.folders[a.id]=clone(h.items[i])}load()}
function openSettings(){$('#clientId').value=clientId();$('#settingsDialog').showModal()}
$('#addAccount').onclick=authorize;$('#allDrives').onclick=()=>{state.selected='all';load()};$('#openSettings').onclick=openSettings;$('#openHelp').onclick=()=>$('#helpDialog').showModal();$('#saveSettings').onclick=e=>{e.preventDefault();let v=$('#clientId').value.trim();if(!v.endsWith('.apps.googleusercontent.com'))return toast('Enter a valid Google Web Client ID.');localStorage.setItem('fd.webClientId',v);$('#settingsDialog').close();toast('Client ID saved on this browser.')};
$('#newFolder').onclick=()=>createFolder().catch(e=>toast(e.message));$('#openBtn').onclick=()=>openChosen().catch(e=>toast(e.message));$('#downloadBtn').onclick=()=>downloadChosen().catch(e=>toast(e.message));$('#renameBtn').onclick=()=>rename().catch(e=>toast(e.message));$('#deleteBtn').onclick=()=>trash().catch(e=>toast(e.message));$('#undoBtn').onclick=undo;$('#copyBtn').onclick=()=>{state.clipboard={mode:'copy',items:chosen()};buttons();toast('Copied. Open a folder and paste.')};$('#cutBtn').onclick=()=>{state.clipboard={mode:'cut',items:chosen()};buttons();toast('Ready to move. Open a folder and paste.')};$('#pasteBtn').onclick=paste;
$('#backBtn').onclick=()=>navigate('back');$('#forwardBtn').onclick=()=>navigate('forward');$('#upBtn').onclick=()=>navigate('up');$('#homeBtn').onclick=()=>navigate('home');$('#uploadInput').onchange=e=>upload([...e.target.files]).catch(x=>toast(x.message));$('#refresh').onclick=load;$('#sort').onchange=e=>{state.sort=e.target.value;render()};$('#search').oninput=e=>{state.query=e.target.value.trim().toLowerCase();render()};$('#selectAll').onchange=e=>{visibleFiles().forEach(f=>{let k=f.accountId+':'+f.id;e.target.checked?state.selectedFiles.add(k):state.selectedFiles.delete(k)});render()};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.altKey&&e.key==='ArrowLeft'){e.preventDefault();navigate('back')}else if(e.altKey&&e.key==='ArrowRight'){e.preventDefault();navigate('forward')}else if(e.altKey&&e.key==='ArrowUp'){e.preventDefault();navigate('up')}else if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();undo()}else if(e.key==='Delete')trash().catch(x=>toast(x.message));else if(e.key==='F2')rename().catch(x=>toast(x.message));else if(e.key==='Enter')openChosen().catch(x=>toast(x.message))});
render();if(!clientId())setTimeout(openSettings,350);
